a5=A.ar(0,"L2-25",2,A.a([A.d("A reversal pattern, usually appearing at the end of an uptrend","M\u1eabu h\xecnh \u0111\u1ea3o chi\u1ec1u, th\u01b0\u1eddng xu\u1ea5t hi\u1ec7n cu\u1ed1i xu h\u01b0\u1edbng t\u0103ng","\u4e00\u79cd\u53cd\u8f6c\u5f62\u6001\uff0c\u901a\u5e38\u51fa\u73b0\u5728\u4e0a\u5347\u8d8b\u52bf\u672b\u7aef","\u53cd\u8ee2\u30d1\u30bf\u30fc\u30f3\u3067\u3001\u901a\u5e38\u4e0a\u6607\u30c8\u30ec\u30f3\u30c9\u306e\u7d42\u308f\u308a\u306b\u73fe\u308c\u308b","\ubc18\uc804 \ud328\ud134\uc73c\ub85c, \ubcf4\ud1b5 \uc0c1\uc2b9 \ucd94\uc138 \ub05d\uc5d0 \ub098\ud0c0\ub0a8"),A.d("A continuation pattern for an uptrend","M\u1eabu h\xecnh ti\u1ebfp di\u1ec5n xu h\u01b0\u1edbng t\u0103ng","\u4e0a\u5347\u8d8b\u52bf\u7684\u5ef6\u7eed\u5f62\u6001","\u4e0a\u6607\u30c8\u30ec\u30f3\u30c9\u306e\u7d99\u7d9a\u30d1\u30bf\u30fc\u30f3","\uc0c1\uc2b9 \ucd94\uc138\uc758 \uc9c0\uc18d \ud328\ud134"),A.d("Only appears on Spot","Ch\u1ec9 xu\u1ea5t hi\u1ec7n tr\xean Spot","\u53ea\u51fa\u73b0\u5728\u73b0\u8d27\u4ea4\u6613\u4e2d","\u73fe\u7269\u53d6\u5f15\u3067\u306e\u307f\u73fe\u308c\u308b","\ud604\ubb3c\uc5d0\uc11c\ub9cc \ub098\ud0c0\ub0a8"),A.d("A type of momentum indicator","M\u1ed9t lo\u1ea1i ch\u1ec9 b\xe1o \u0111\u1ed9ng l\u01b0\u1ee3ng","\u4e00\u79cd\u52a8\u91cf\u6307\u6807","\u30e2\u30e1\u30f3\u30bf\u30e0\u6307\u6a19\u306e\u4e00\u7a2e","\ubaa8\uba58\ud140 \uc9c0\ud45c\uc758 \ud55c \uc885\ub958")],f9),a6,a5)
