o=A.ar(0,"L3-05",3,A.a([A.d("A dip below the accumulation range to sweep liquidity/stops before reversing up","C\xfa th\u1ecdc gi\xe1 xu\u1ed1ng d\u01b0\u1edbi v\xf9ng t\xedch lu\u1ef9 \u0111\u1ec3 qu\xe9t thanh kho\u1ea3n/d\u1eebng l\u1ed7 tr\u01b0\u1edbc khi \u0111\u1ea3o chi\u1ec1u t\u0103ng","\u8dcc\u7834\u5438\u7b79\u533a\u95f4\u4ee5\u626b\u8361\u6d41\u52a8\u6027/\u6b62\u635f\u5355\uff0c\u968f\u540e\u53cd\u8f6c\u4e0a\u6da8","\u53cd\u8ee2\u4e0a\u6607\u524d\u306b\u8cb7\u3044\u96c6\u3081\u5e2f\u306e\u4e0b\u3092\u308f\u305a\u304b\u306b\u7a81\u304d\u629c\u3051\u3066\u6d41\u52d5\u6027/\u640d\u5207\u308a\u3092\u72e9\u308b\u3053\u3068","\ubc18\uc804 \uc0c1\uc2b9 \uc804, \ub9e4\uc9d1 \uad6c\uac04 \uc544\ub798\ub85c \uc0b4\uc9dd \ub6ab\uc5b4 \uc720\ub3d9\uc131/\uc190\uc808\uc744 \uc4f8\uc5b4\uac00\ub294 \uac83"),A.d("A steady, long-term price rise phase","Giai \u0111o\u1ea1n gi\xe1 t\u0103ng \u1ed5n \u0111\u1ecbnh d\xe0i h\u1ea1n","\u7a33\u5b9a\u7684\u957f\u671f\u4ef7\u683c\u4e0a\u6da8\u9636\u6bb5","\u5b89\u5b9a\u3057\u305f\u9577\u671f\u4e0a\u6607\u5c40\u9762","\uc548\uc815\uc801\uc774\uace0 \uc7a5\uae30\uc801\uc778 \uc0c1\uc2b9 \ub2e8\uacc4"),A.d("A simple reversal candle pattern","M\u1ed9t lo\u1ea1i n\u1ebfn \u0111\u1ea3o chi\u1ec1u \u0111\u01a1n gi\u1ea3n","\u4e00\u79cd\u7b80\u5355\u7684\u53cd\u8f6cK\u7ebf\u5f62\u6001","\u5358\u7d14\u306a\u53cd\u8ee2\u30ed\u30fc\u30bd\u30af\u8db3\u30d1\u30bf\u30fc\u30f3","\ub2e8\uc21c\ud55c \ubc18\uc804 \uce94\ub4e4 \ud328\ud134"),A.d("Another name for Take Profit","T\xean g\u1ecdi kh\xe1c c\u1ee7a Take Profit","\u6b62\u76c8\u7684\u53e6\u4e00\u79cd\u8bf4\u6cd5","\u5229\u78ba\u306e\u5225\u306e\u8a00\u3044\u65b9","\uc775\uc808\uc758 \ub2e4\ub978 \ud45c\ud604")],e6),n,o)
